PATCH = '--- a/app/build.gradle.kts\n+++ b/app/build.gradle.kts\n@@ -24,8 +24,8 @@\n         applicationId = "com.earthunlock.app"\n         minSdk = 26\n         targetSdk = 36\n-        versionCode = 103\n-        versionName = "0.10.50"\n+        versionCode = 104\n+        versionName = "0.10.51"\n         testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"\n     }\n     testBuildType = "release"\n@@ -50,7 +50,11 @@\n             if (hasReleaseSigning) {\n                 signingConfig = signingConfigs.getByName("release")\n             }\n-            isMinifyEnabled = false // Enable shrinking only after device/Play internal-track validation.\n+            // Google Play DEX quality: R8 shrinking, optimization and obfuscation.\n+            isMinifyEnabled = true\n+            isShrinkResources = true\n+            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")\n+            testProguardFiles("proguard-android-test.pro")\n         }\n     }\n     compileOptions {\n--- /dev/null\n+++ b/app/proguard-rules.pro\n@@ -0,0 +1,28 @@\n+# The platform and Firebase / Google Play Services dependencies provide consumer\n+# rules for their runtime components. App backup documents use explicit Map\n+# keys, not reflection over obfuscated application data classes.\n+# Do not use a blanket -keep of Firebase, GMS, Kotlin or the app.\n+\n+# Small, bounded instrumentation API: preserve only the app classes directly\n+# invoked across the test APK boundary. The rest of the production app and\n+# dependencies remain eligible for shrinking, optimization and obfuscation.\n+-keep,allowoptimization class com.earthunlock.app.TrackStore { *; }\n+-keep,allowoptimization class com.earthunlock.app.TrackPoint { *; }\n+-keep,allowoptimization class com.earthunlock.app.ExploredCell { *; }\n+-keep,allowoptimization class com.earthunlock.app.TrackMath { *; }\n+-keep,allowoptimization class com.earthunlock.app.FogContours { *; }\n+-keep,allowoptimization class com.earthunlock.app.FogContours$Shape { *; }\n+-keep,allowoptimization class com.earthunlock.app.FogOverlay { *; }\n+\n+# The rendering regression calls this network-disable method only in tests.\n+-keepclassmembers,allowoptimization class org.osmdroid.views.MapView {\n+    public void setUseDataConnection(boolean);\n+}\n+\n+# Preserve meaningful source lines in crash reporting; R8 mapping is embedded\n+# in the bundle and supplies the actual deobfuscation information.\n+-keepattributes SourceFile,LineNumberTable\n+\n+# AndroidJUnitRunner shares the app AndroidX tracing dependency; preserve\n+# this narrow API so the signed release remains instrumentable after R8.\n+-keep class androidx.tracing.** { *; }\n--- /dev/null\n+++ b/app/proguard-android-test.pro\n@@ -0,0 +1,9 @@\n+# JUnit discovers these classes and methods reflectively in the test APK only.\n+-keep class com.earthunlock.app.TrackingStorageInstrumentedTest { *; }\n+-keep class com.earthunlock.app.FogRenderingInstrumentedTest { *; }\n+-keep class com.earthunlock.app.ReleaseSdkInstrumentedTest { *; }\n+-keep class androidx.test.** { *; }\n+-keep class org.junit.** { *; }\n+-keep class org.hamcrest.** { *; }\n+-keep class junit.** { *; }\n+-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod\n--- /dev/null\n+++ b/app/src/androidTest/java/com/earthunlock/app/ReleaseSdkInstrumentedTest.kt\n@@ -0,0 +1,34 @@\n+package com.earthunlock.app\n+\n+import androidx.test.ext.junit.runners.AndroidJUnit4\n+import androidx.test.platform.app.InstrumentationRegistry\n+import com.google.android.gms.auth.api.signin.GoogleSignIn\n+import com.google.android.gms.auth.api.signin.GoogleSignInOptions\n+import com.google.firebase.FirebaseApp\n+import com.google.firebase.auth.FirebaseAuth\n+import com.google.firebase.firestore.FirebaseFirestore\n+import org.junit.Assert.*\n+import org.junit.Test\n+import org.junit.runner.RunWith\n+\n+/** Exercise SDK initialization and dynamic resources in the exact R8 release.\n+ * No account login, user data, Firestore read/write or other backend mutation. */\n+@RunWith(AndroidJUnit4::class)\n+class ReleaseSdkInstrumentedTest {\n+    @Test fun firebaseAndGoogleSignInConfigurationSurviveResourceShrinking() {\n+        val ctx = InstrumentationRegistry.getInstrumentation().targetContext\n+        assertEquals("0.10.51", ctx.packageManager.getPackageInfo(ctx.packageName, 0).versionName)\n+        assertEquals("com.earthunlock.app", ctx.packageName)\n+        assertEquals("my-earth-a73cb", FirebaseApp.getInstance().options.projectId)\n+        val clientId = ctx.resources.getIdentifier("default_web_client_id", "string", ctx.packageName)\n+        assertNotEquals("Dynamically looked-up OAuth resource must survive shrinking", 0, clientId)\n+        val oauth = ctx.getString(clientId)\n+        assertTrue("Expected Google web OAuth client", oauth.endsWith(".apps.googleusercontent.com"))\n+        val options = GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)\n+            .requestIdToken(oauth).requestEmail().build()\n+        assertNotNull(GoogleSignIn.getClient(ctx, options).signInIntent)\n+        assertNotNull(FirebaseAuth.getInstance())\n+        // Constructing a Firestore reference does not read or write cloud data.\n+        assertNotNull(FirebaseFirestore.getInstance().collection("exploration_backups"))\n+    }\n+}\n--- a/app/src/androidTest/java/com/earthunlock/app/TrackingStorageInstrumentedTest.kt\n+++ b/app/src/androidTest/java/com/earthunlock/app/TrackingStorageInstrumentedTest.kt\n@@ -54,8 +54,8 @@\n     }\n \n     @Test fun seedBeforeUpgrade() {\n-        // This method is invoked against the signed 0.10.49 APK on a fresh emulator.\n-        assertEquals("0.10.49", ctx.packageManager.getPackageInfo(ctx.packageName, 0).versionName)\n+        // This method is invoked against the signed 0.10.50 APK on a fresh emulator.\n+        assertEquals("0.10.50", ctx.packageManager.getPackageInfo(ctx.packageName, 0).versionName)\n         TrackStore(ctx).use { store ->\n             assertEquals("Emulator must have an empty GPS history", 0, store.count())\n             (initial + continuation).forEach { store.recordAndReveal(it, 12.0) }\n@@ -69,7 +69,7 @@\n         }\n     }\n     @Test fun verifyAfterUpgrade() {\n-        assertEquals("0.10.50", ctx.packageManager.getPackageInfo(ctx.packageName, 0).versionName)\n+        assertEquals("0.10.51", ctx.packageManager.getPackageInfo(ctx.packageName, 0).versionName)\n         TrackStore(ctx).use { store ->\n             verify("initial", store)\n             assertEquals(initial.last(), store.lastPoint())\n--- /dev/null\n+++ b/app/src/main/res/raw/my_earth_firebase_keep.xml\n@@ -0,0 +1,4 @@\n+<?xml version="1.0" encoding="utf-8"?>\n+<!-- Google Services / Firebase SDK resolve some generated resource names at runtime. -->\n+<resources xmlns:tools="http://schemas.android.com/tools"\n+    tools:keep="@string/default_web_client_id,@string/google_*,@string/gcm_defaultSenderId,@string/project_id,@string/firebase_database_url" />\n--- a/gradle.properties\n+++ b/gradle.properties\n@@ -1,3 +1,3 @@\n-org.gradle.jvmargs=-Xmx2g -Dfile.encoding=UTF-8\n+org.gradle.jvmargs=-Xmx4g -Dfile.encoding=UTF-8\n android.useAndroidX=true\n kotlin.code.style=official\n--- a/scripts/verify-play-release-policy.py\n+++ b/scripts/verify-play-release-policy.py\n@@ -72,8 +72,11 @@\n \n \n assert \'collection("exploration_backups").document(user.uid).collection("chunks")\' in manager\n-assert \'versionCode = 103\' in gradle\n-assert \'versionName = "0.10.50"\' in gradle\n+assert \'versionCode = 104\' in gradle\n+assert \'versionName = "0.10.51"\' in gradle\n+assert \'isMinifyEnabled = true\' in gradle\n+assert \'isShrinkResources = true\' in gradle\n+assert \'proguard-android-optimize.txt\' in gradle\n assert \'android:usesCleartextTraffic="false"\' in manifest\n assert "ACCESS_BACKGROUND_LOCATION" not in manifest\n \n'
